const dialog=document.querySelector('#panel'),title=document.querySelector('#panel-title'),body=document.querySelector('#panel-body');
const messages=[['guild','商會','哪有每次買都被狙擊的'],['private','私訊','我會笑死'],['world','世界','我會笑死，哪有每次買都被狙擊的，哈哈哈哈']];
let returnFocus,feedbackTimer;
function openPanel(kind,trigger){returnFocus=trigger;title.textContent=kind==='chat'?'聊天':'熱門事件';body.replaceChildren();if(kind==='chat'){for(const [color,channel,text] of messages){const item=document.createElement('div');item.className='message';const label=document.createElement('b');label.className=color;label.textContent=`[${channel}] FOMO價值投資者`;item.append(label,document.createTextNode(text));body.append(item)}}else{for(const [name,meta] of [['BTC 趨勢預測','1,280 人參與 · 18:42'],['降息觀點 PK','多 63% · 空 37% · 02:15'],['商會週末挑戰','32 商會參戰 · 1 天']]){const item=document.createElement('div');item.className='event-card';item.textContent=name;const small=document.createElement('small');small.textContent=meta;item.append(small);body.append(item)}}dialog.showModal()}
document.querySelectorAll('[data-panel]').forEach(el=>el.addEventListener('click',()=>openPanel(el.dataset.panel,el)));
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>returnFocus?.focus());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
document.querySelectorAll('button:not([data-panel]):not(.close)').forEach(el=>el.addEventListener('click',()=>{const notice=document.querySelector('.feedback');notice.textContent=el.dataset.nav||el.dataset.label||el.getAttribute('aria-label')||el.textContent.trim();notice.classList.add('visible');clearTimeout(feedbackTimer);feedbackTimer=setTimeout(()=>notice.classList.remove('visible'),1300)}));
